// Command cooked emits ../../rand-cooked.ts: the rngCooked table from the Go
// toolchain's own math/rand source, split into uint32 halves.
//
// The table is unexported, so this reads $GOROOT/src/math/rand/rng.go as
// text. Run from the repository root:
//
//	./scripts/go-local run ./server/static/src/engine/testdata/gen/cooked
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

func main() {
	src, err := os.ReadFile(filepath.Join(runtime.GOROOT(), "src", "math", "rand", "rng.go"))
	if err != nil {
		panic(err)
	}
	text := string(src)
	start := strings.Index(text, "rngCooked [rngLen]int64 = [...]int64{")
	if start < 0 {
		panic("rngCooked not found")
	}
	end := strings.Index(text[start:], "\n\t}")
	body := text[start : start+end]
	body = body[strings.Index(body, "{")+1:]
	nums := regexp.MustCompile(`-?\d+`).FindAllString(body, -1)
	if len(nums) != 607 {
		panic(fmt.Sprintf("expected 607 values, found %d", len(nums)))
	}
	var b strings.Builder
	b.WriteString("// GENERATED by testdata/gen/cooked from " + runtime.Version() + " math/rand/rng.go. DO NOT EDIT.\n")
	b.WriteString("// rngCooked[i] as [high 32 bits, low 32 bits], flattened: 607 pairs.\n")
	b.WriteString("export const RNG_COOKED: readonly number[] = [\n")
	for _, n := range nums {
		v, err := strconv.ParseInt(n, 10, 64)
		if err != nil {
			panic(err)
		}
		u := uint64(v)
		fmt.Fprintf(&b, "\t0x%08x, 0x%08x,\n", uint32(u>>32), uint32(u))
	}
	b.WriteString("];\n")
	if err := os.WriteFile("server/static/src/engine/rand-cooked.ts", []byte(b.String()), 0644); err != nil {
		panic(err)
	}
}
